//! Tests of `TestXmlOutputParser`, second set (review exec-2 round 2): the reviewer's probe
//! documents (`~/.cache/blaze/work/review-exec-2/xml2/`) and the round-2 fixer's
//! (`~/.cache/blaze/work/workers-3/xml/cases5`, `cases6`), with the results of Bazel's own
//! `TestXmlOutputParser` on the oracle's embedded JDK 25.0.2 (`XmlProbe` of
//! `~/.cache/blaze/work/exec-fix-1/xmlprobe/`). `None` is a document Java rejects.
//! Generated by `~/.cache/blaze/work/workers-3/xml/make_review_tests.py`; edit the generator.

use blaze_exec::exec::test_xml_output_parser::TestXmlOutputParser;
use blaze_protos::blaze::TestCase;
use blaze_protos::blaze::test_case::{Status, Type};

/// (name, run duration in ms, type, status) of each node, in pre-order.
type Node = (Option<String>, Option<i64>, Type, Status);

/// A part of a large document: bytes, or bytes repeated.
enum Seg {
    Lit(&'static [u8]),
    Rep(&'static [u8], usize),
}

fn doc(segs: &[Seg]) -> Vec<u8> {
    let mut out = Vec::new();
    for seg in segs {
        match seg {
            Seg::Lit(b) => out.extend_from_slice(b),
            Seg::Rep(b, n) => {
                for _ in 0..*n {
                    out.extend_from_slice(b);
                }
            }
        }
    }
    out
}

fn preorder(test_case: &TestCase, out: &mut Vec<(Option<String>, Option<i64>, Type, Status)>) {
    out.push((
        test_case.name.clone(),
        test_case.run_duration_millis,
        test_case.r#type(),
        test_case.status(),
    ));
    for child in &test_case.child {
        preorder(child, out);
    }
}

/// A long expected name, written like a large document.
fn long_name(segs: &[Seg]) -> Option<String> {
    Some(String::from_utf8(doc(segs)).expect("UTF-8 name"))
}

fn check(document: &[u8], expected: Option<Vec<Node>>) {
    let result = TestXmlOutputParser::new()
        .parse_xml_into_test_result(&mut &document[..])
        .ok()
        .flatten();
    let actual = result.map(|test_case| {
        let mut nodes = Vec::new();
        preorder(&test_case, &mut nodes);
        nodes
    });
    assert_eq!(actual, expected);
}

